templates.react:
export function BlogCard({
  title = "{{title}}",
  excerpt = "{{excerpt}}",
  category = "{{category}}",
  readTime = "{{readTime}}",
  accent = "{{accent}}",
}) {
  const badge = {
    Guide: { background: "#A8E6C133", color: "#1b5c38" },
    News: { background: "#BFD9F233", color: "#1b3f5c" },
    Opinion: { background: "#F5C2E033", color: "#7a1b52" },
  }[category] ?? {};
  return (
    <article style={{ maxWidth: 320, font: "16px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2",
      borderRadius: 14, overflow: "hidden", border: "1px solid #24143018" }}>
      <div role="img" aria-label="Article thumbnail" style={{ height: 140, background: `linear-gradient(135deg, ${accent}, #FAF7F2)` }} />
      <div style={{ padding: 16 }}>
        <span style={{ display: "inline-block", fontSize: 11, fontWeight: 700, textTransform: "uppercase",
          letterSpacing: "0.04em", padding: "3px 8px", borderRadius: 999, marginBottom: 10, ...badge }}>{category}</span>
        <h3 style={{ margin: "0 0 8px", fontSize: 18, fontWeight: 700 }}>{title}</h3>
        <p style={{ margin: "0 0 12px", fontSize: 14, color: "#241430cc" }}>{excerpt}</p>
        <span style={{ fontSize: 12, color: "#24143088" }}>{readTime}</span>
      </div>
    </article>
  );
}
